package com.primehr.rsp.evaluation.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import com.primehr.shared.exception.IllegalLifecycleTransitionException;import jakarta.persistence.*;import org.hibernate.annotations.Nationalized;import java.time.*;import java.util.*;
@Entity @Table(name="rsp_hrmpsb_meeting") public class HrmpsbMeeting extends RspAuditedEntity{
 public enum Status{DRAFT,SCHEDULED,IN_DELIBERATION,FINALIZED,CANCELLED}
 @Column(name="proceeding_id",nullable=false,length=36)private String proceedingId;@Column(name="meeting_revision",nullable=false)private int meetingRevision;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private Status status;@Column(name="scheduled_at",nullable=false)private Instant scheduledAt;@Column(name="time_zone",nullable=false,length=80)private String timeZone;@Column(length=500)private String venue;@Column(nullable=false,length=4000)private String agenda;@Nationalized @Column(length=32000)private String minutes;@Column(name="quorum_required",nullable=false)private int quorumRequired;@Column(name="finalized_by",length=100)private String finalizedBy;@Column(name="finalized_at")private Instant finalizedAt;@Column(name="finalization_reason",length=2000)private String finalizationReason;
 protected HrmpsbMeeting(){}public HrmpsbMeeting(String agency,String proceeding,int revision,Instant scheduled,String zone,String venue,String agenda,int quorum){super(agency);proceedingId=requiredText(proceeding,"proceedingId");if(revision<1||quorum<1)throw new IllegalArgumentException("Meeting revision and quorum must be positive");meetingRevision=revision;scheduledAt=Objects.requireNonNull(scheduled);timeZone=requiredText(zone,"timeZone");ZoneId.of(timeZone);this.venue=optionalText(venue);this.agenda=requiredText(agenda,"agenda");quorumRequired=quorum;status=Status.DRAFT;}
 public void update(Instant scheduled,String zone,String venue,String agenda,int quorum,String minutes){if(status==Status.FINALIZED||status==Status.CANCELLED)throw new IllegalLifecycleTransitionException("A final meeting is immutable");scheduledAt=Objects.requireNonNull(scheduled);timeZone=requiredText(zone,"timeZone");ZoneId.of(timeZone);this.venue=optionalText(venue);this.agenda=requiredText(agenda,"agenda");if(quorum<1)throw new IllegalArgumentException("quorumRequired must be positive");quorumRequired=quorum;this.minutes=optionalText(minutes);}public void schedule(){if(status!=Status.DRAFT)throw new IllegalLifecycleTransitionException("Only a DRAFT meeting may be scheduled");status=Status.SCHEDULED;}public void begin(){if(status!=Status.SCHEDULED)throw new IllegalLifecycleTransitionException("Only a SCHEDULED meeting may begin");status=Status.IN_DELIBERATION;}public void finalizeMeeting(String actor,String reason,Instant at){if(status!=Status.IN_DELIBERATION)throw new IllegalLifecycleTransitionException("Only an IN_DELIBERATION meeting may be finalized");if(minutes==null)throw new IllegalLifecycleTransitionException("Meeting minutes are required");finalizedBy=requiredText(actor,"actor");finalizationReason=requiredText(reason,"reason");finalizedAt=Objects.requireNonNull(at);status=Status.FINALIZED;}
 public String getProceedingId(){return proceedingId;}public int getMeetingRevision(){return meetingRevision;}public Status getStatus(){return status;}public Instant getScheduledAt(){return scheduledAt;}public String getTimeZone(){return timeZone;}public String getVenue(){return venue;}public String getAgenda(){return agenda;}public String getMinutes(){return minutes;}public int getQuorumRequired(){return quorumRequired;}public String getFinalizedBy(){return finalizedBy;}public Instant getFinalizedAt(){return finalizedAt;}
}
